// -------- RESETS TYPE -------- //

export interface RESETS_t {  // @ 0x4000C000
    RESET: $Reg                         // /*!< (@ 0x00000000) Reset control. If a bit is set it means the peripheral is in reset. 0 means the peripheral's reset is deasserted. */
    WDSEL: $Reg                         // /*!< (@ 0x00000004) Watchdog select. If a bit is set then the watchdog will reset this peripheral when the watchdog fires. */
    RESET_DONE: $Reg                    // /*!< (@ 0x00000008) Reset done. If a bit is set then a reset done signal has been returned by the peripheral. This indicates that the peripheral's registers are ready to be accessed. */
}

